-- FreightFlow banking-service schema (ADR 0004, ADR 0005, ADR 0006, ADR 0007).
-- Time-ordered UUIDv7 primary keys generated by Hibernate 7 (UuidVersion7Strategy).

CREATE SEQUENCE account_number_seq START WITH 1000 INCREMENT BY 1;

CREATE TABLE accounts (
    id               UUID PRIMARY KEY,
    account_number   VARCHAR(16) NOT NULL UNIQUE,
    holder_reference VARCHAR(120) NOT NULL,
    account_type     VARCHAR(32) NOT NULL,
    currency         VARCHAR(3) NOT NULL,
    status           VARCHAR(16) NOT NULL,
    balance          NUMERIC(19, 4) NOT NULL DEFAULT 0.0000,
    created_at       TIMESTAMPTZ NOT NULL,
    updated_at       TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_accounts_number_format CHECK (account_number ~ '^FF[0-9]{2}[A-Z]{3}[0-9]{9}$'),
    CONSTRAINT chk_accounts_type CHECK (account_type IN ('CUSTOMER', 'CLEARING', 'FREIGHT_REVENUE', 'FX_POSITION')),
    CONSTRAINT chk_accounts_currency CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT chk_accounts_status CHECK (status IN ('ACTIVE', 'FROZEN', 'CLOSED')),
    CONSTRAINT chk_accounts_customer_non_negative CHECK (account_type <> 'CUSTOMER' OR balance >= 0)
);

CREATE UNIQUE INDEX uq_accounts_system_type_currency
    ON accounts (account_type, currency)
    WHERE account_type <> 'CUSTOMER';

-- System accounts in every environment: CLEARING, FREIGHT_REVENUE and FX_POSITION for NAD, ZAR and EUR.
-- Account numbers carry ISO 7064 MOD 97-10 check digits.
