    ('01930000-0000-7000-8000-000000000003', 'FF33NAD000000003', 'SYSTEM:FX_POSITION:NAD',     'FX_POSITION',     'NAD', 'ACTIVE', 0.0000, '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z'),
    ('01930000-0000-7000-8000-000000000004', 'FF29ZAR000000001', 'SYSTEM:CLEARING:ZAR',        'CLEARING',        'ZAR', 'ACTIVE', 0.0000, '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z'),
    ('01930000-0000-7000-8000-000000000005', 'FF02ZAR000000002', 'SYSTEM:FREIGHT_REVENUE:ZAR', 'FREIGHT_REVENUE', 'ZAR', 'ACTIVE', 0.0000, '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z'),
    ('01930000-0000-7000-8000-000000000006', 'FF72ZAR000000003', 'SYSTEM:FX_POSITION:ZAR',     'FX_POSITION',     'ZAR', 'ACTIVE', 0.0000, '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z'),
