    ('01930000-0000-7000-8000-000000000009', 'FF57EUR000000003', 'SYSTEM:FX_POSITION:EUR',     'FX_POSITION',     'EUR', 'ACTIVE', 0.0000, '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z');

CREATE TABLE fx_quotes (
    id            UUID PRIMARY KEY,
    sell_currency VARCHAR(3) NOT NULL,
    buy_currency  VARCHAR(3) NOT NULL,
    sell_amount   NUMERIC(19, 4) NOT NULL,
    buy_amount    NUMERIC(19, 4) NOT NULL,
    mid_rate      NUMERIC(19, 8) NOT NULL,
    spread        NUMERIC(10, 6) NOT NULL,
    rate          NUMERIC(19, 8) NOT NULL,
    expires_at    TIMESTAMPTZ NOT NULL,
    used_at       TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_fx_quotes_currencies_differ CHECK (sell_currency <> buy_currency),
    CONSTRAINT chk_fx_quotes_positive_amounts CHECK (sell_amount > 0 AND buy_amount > 0 AND mid_rate > 0 AND rate > 0),
    CONSTRAINT chk_fx_quotes_spread CHECK (spread >= 0 AND spread < 1)
);

CREATE TABLE journal_entries (
    id                UUID PRIMARY KEY,
    entry_type        VARCHAR(32) NOT NULL,
    reference         VARCHAR(160) NOT NULL,
    reverses_entry_id UUID UNIQUE REFERENCES journal_entries(id),
    fx_quote_id       UUID REFERENCES fx_quotes(id),
    fx_rate           NUMERIC(19, 8),
    created_at        TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_journal_entries_type CHECK (entry_type IN ('DEPOSIT', 'TRANSFER', 'FX_TRANSFER', 'REVERSAL')),
    CONSTRAINT chk_journal_entries_reversal_ref CHECK (
        (entry_type = 'REVERSAL' AND reverses_entry_id IS NOT NULL)
        OR (entry_type <> 'REVERSAL' AND reverses_entry_id IS NULL)
    ),
    CONSTRAINT chk_journal_entries_fx_rate CHECK (fx_rate IS NULL OR fx_rate > 0)
);

CREATE TABLE postings (
    id               UUID PRIMARY KEY,
    journal_entry_id UUID NOT NULL REFERENCES journal_entries(id),
    account_id       UUID NOT NULL REFERENCES accounts(id),
    amount           NUMERIC(19, 4) NOT NULL,
    currency         VARCHAR(3) NOT NULL,
    running_balance  NUMERIC(19, 4) NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_postings_non_zero_amount CHECK (amount <> 0),
    CONSTRAINT chk_postings_currency CHECK (currency ~ '^[A-Z]{3}$')
);

CREATE INDEX idx_postings_journal_entry ON postings (journal_entry_id);
CREATE INDEX idx_postings_account_statement ON postings (account_id, created_at DESC, id DESC);

CREATE TABLE transfers (
    id                UUID PRIMARY KEY,
    journal_entry_id  UUID NOT NULL UNIQUE REFERENCES journal_entries(id),
    source_account_id UUID NOT NULL REFERENCES accounts(id),
    target_account_id UUID NOT NULL REFERENCES accounts(id),
    source_amount     NUMERIC(19, 4) NOT NULL,
    source_currency   VARCHAR(3) NOT NULL,
    target_amount     NUMERIC(19, 4) NOT NULL,
    target_currency   VARCHAR(3) NOT NULL,
    reference         VARCHAR(160) NOT NULL,
    fx_quote_id       UUID UNIQUE REFERENCES fx_quotes(id),
    fx_rate           NUMERIC(19, 8),
    created_at        TIMESTAMPTZ NOT NULL,
    CONSTRAINT chk_transfers_distinct_accounts CHECK (source_account_id <> target_account_id),
    CONSTRAINT chk_transfers_positive_amounts CHECK (source_amount > 0 AND target_amount > 0),
    CONSTRAINT chk_transfers_fx_consistency CHECK (
        (source_currency = target_currency AND fx_quote_id IS NULL AND fx_rate IS NULL AND source_amount = target_amount)
        OR (source_currency <> target_currency AND fx_quote_id IS NOT NULL AND fx_rate IS NOT NULL)
    )
);

CREATE TABLE idempotency_keys (
    scope           VARCHAR(64) NOT NULL,
    idempotency_key VARCHAR(128) NOT NULL,
    request_hash    CHAR(64) NOT NULL,
    status          VARCHAR(16) NOT NULL,
    http_status     INT,
    response_body   TEXT,
    created_at      TIMESTAMPTZ NOT NULL,
    expires_at      TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (scope, idempotency_key),
    CONSTRAINT chk_idempotency_status CHECK (status IN ('IN_PROGRESS', 'COMPLETED')),
    CONSTRAINT chk_idempotency_completed_fields CHECK (
        (status = 'IN_PROGRESS' AND http_status IS NULL AND response_body IS NULL)
        OR (status = 'COMPLETED' AND http_status IS NOT NULL AND response_body IS NOT NULL)
    )
);

CREATE INDEX idx_idempotency_keys_expires_at ON idempotency_keys (expires_at);

-- Append-only ledger: UPDATE and DELETE are unconditionally rejected on journal_entries and postings.
CREATE OR REPLACE FUNCTION reject_ledger_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION '% on % is prohibited: the ledger is append-only', TG_OP, TG_TABLE_NAME
        USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER trg_journal_entries_append_only
    BEFORE UPDATE OR DELETE ON journal_entries
    FOR EACH ROW
    EXECUTE FUNCTION reject_ledger_mutation();

CREATE TRIGGER trg_postings_append_only
    BEFORE UPDATE OR DELETE ON postings
    FOR EACH ROW
    EXECUTE FUNCTION reject_ledger_mutation();

-- Double-entry invariant checked at transaction commit (DEFERRABLE INITIALLY DEFERRED):
-- 1. Every journal entry has at least two postings.
-- 2. Every posting's currency matches its account's currency.
-- 3. Within a journal entry, postings sum to zero per currency.
CREATE OR REPLACE FUNCTION verify_journal_entry_balance()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    target_entry_id UUID;
    posting_count   INT;
    bad_currency    VARCHAR(3);
    unbalanced_curr VARCHAR(3);
    unbalanced_sum  NUMERIC(19, 4);
BEGIN
    IF TG_TABLE_NAME = 'journal_entries' THEN
        target_entry_id := NEW.id;
    ELSE
        target_entry_id := NEW.journal_entry_id;
    END IF;

    SELECT COUNT(*) INTO posting_count
    FROM postings
    WHERE journal_entry_id = target_entry_id;

    IF posting_count < 2 THEN
        RAISE EXCEPTION 'journal_entry % has % posting(s); at least 2 are required', target_entry_id, posting_count
            USING ERRCODE = '23514';
    END IF;

    SELECT p.currency INTO bad_currency
    FROM postings p
    JOIN accounts a ON a.id = p.account_id
    WHERE p.journal_entry_id = target_entry_id
      AND p.currency <> a.currency
    LIMIT 1;

    IF bad_currency IS NOT NULL THEN
        RAISE EXCEPTION 'journal_entry % has a posting in % that does not match its account currency',
            target_entry_id, bad_currency
            USING ERRCODE = '23514';
    END IF;

    SELECT currency, SUM(amount) INTO unbalanced_curr, unbalanced_sum
    FROM postings
    WHERE journal_entry_id = target_entry_id
    GROUP BY currency
    HAVING SUM(amount) <> 0
    LIMIT 1;

    IF unbalanced_curr IS NOT NULL THEN
        RAISE EXCEPTION 'journal_entry % is unbalanced in %: postings sum to %',
            target_entry_id, unbalanced_curr, unbalanced_sum
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_journal_entry_balanced
    AFTER INSERT ON journal_entries
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW
    EXECUTE FUNCTION verify_journal_entry_balance();

CREATE CONSTRAINT TRIGGER trg_posting_entry_balanced
    AFTER INSERT ON postings
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW
    EXECUTE FUNCTION verify_journal_entry_balance();
